SELECT CAST(CASE WHEN COUNT("store_sales"."ss_quantity") = 0 THEN NULL ELSE COALESCE(SUM("store_sales"."ss_quantity"), 0) END / COUNT("store_sales"."ss_quantity") AS INTEGER), CAST(CASE WHEN COUNT("store_sales"."ss_ext_sales_price") = 0 THEN NULL ELSE COALESCE(SUM("store_sales"."ss_ext_sales_price"), 0) END / COUNT("store_sales"."ss_ext_sales_price") AS DECIMAL(19, 0)), CAST(CASE WHEN COUNT("store_sales"."ss_ext_wholesale_cost") = 0 THEN NULL ELSE COALESCE(SUM("store_sales"."ss_ext_wholesale_cost"), 0) END / COUNT("store_sales"."ss_ext_wholesale_cost") AS DECIMAL(19, 0)), CASE WHEN COUNT("store_sales"."ss_ext_wholesale_cost") = 0 THEN NULL ELSE COALESCE(SUM("store_sales"."ss_ext_wholesale_cost"), 0) END
FROM "store_sales",
"store",
"customer_demographics",
"household_demographics",
"customer_address",
"date_dim"
WHERE "store"."s_store_sk" = "store_sales"."ss_store_sk" AND "store_sales"."ss_sold_date_sk" = "date_dim"."d_date_sk" AND "date_dim"."d_year" = 2001 AND ("store_sales"."ss_hdemo_sk" = "household_demographics"."hd_demo_sk" AND ("customer_demographics"."cd_demo_sk" = "store_sales"."ss_cdemo_sk" AND "customer_demographics"."cd_marital_status" = 'D') AND (CAST("customer_demographics"."cd_education_status" AS VARCHAR(11)) = '2 yr Degree' AND "store_sales"."ss_sales_price" >= 100.00 AND ("store_sales"."ss_sales_price" <= 150.00 AND "household_demographics"."hd_dep_count" = 3)) OR "store_sales"."ss_hdemo_sk" = "household_demographics"."hd_demo_sk" AND ("customer_demographics"."cd_demo_sk" = "store_sales"."ss_cdemo_sk" AND "customer_demographics"."cd_marital_status" = 'S') AND (CAST("customer_demographics"."cd_education_status" AS VARCHAR(9)) = 'Secondary' AND "store_sales"."ss_sales_price" >= 50.00 AND ("store_sales"."ss_sales_price" <= 100.00 AND "household_demographics"."hd_dep_count" = 1)) OR "store_sales"."ss_hdemo_sk" = "household_demographics"."hd_demo_sk" AND ("customer_demographics"."cd_demo_sk" = "store_sales"."ss_cdemo_sk" AND "customer_demographics"."cd_marital_status" = 'W') AND (CAST("customer_demographics"."cd_education_status" AS VARCHAR(15)) = 'Advanced Degree' AND "store_sales"."ss_sales_price" >= 150.00 AND ("store_sales"."ss_sales_price" <= 200.00 AND "household_demographics"."hd_dep_count" = 1))) AND ("store_sales"."ss_addr_sk" = "customer_address"."ca_address_sk" AND CAST("customer_address"."ca_country" AS VARCHAR(13)) = 'United States' AND (CAST("customer_address"."ca_state" AS VARCHAR(2)) = 'CO' OR CAST("customer_address"."ca_state" AS VARCHAR(2)) = 'IL' OR CAST("customer_address"."ca_state" AS VARCHAR(2)) = 'MN') AND "store_sales"."ss_net_profit" >= 100 AND "store_sales"."ss_net_profit" <= 200 OR "store_sales"."ss_addr_sk" = "customer_address"."ca_address_sk" AND CAST("customer_address"."ca_country" AS VARCHAR(13)) = 'United States' AND (CAST("customer_address"."ca_state" AS VARCHAR(2)) = 'OH' OR CAST("customer_address"."ca_state" AS VARCHAR(2)) = 'MT' OR CAST("customer_address"."ca_state" AS VARCHAR(2)) = 'NM') AND "store_sales"."ss_net_profit" >= 150 AND "store_sales"."ss_net_profit" <= 300 OR "store_sales"."ss_addr_sk" = "customer_address"."ca_address_sk" AND CAST("customer_address"."ca_country" AS VARCHAR(13)) = 'United States' AND (CAST("customer_address"."ca_state" AS VARCHAR(2)) = 'TX' OR CAST("customer_address"."ca_state" AS VARCHAR(2)) = 'MO' OR CAST("customer_address"."ca_state" AS VARCHAR(2)) = 'MI') AND "store_sales"."ss_net_profit" >= 50 AND "store_sales"."ss_net_profit" <= 250)
